      (fun τ => energyInJoules (process.heatIntoMaterial τ))
      (Set.Icc (0 : ℝ) 1)
  equationOfState :
    ∀ τ ∈ Set.Icc (0 : ℝ) 1,
      temperatureAlongProcessInKelvin process τ *
            magnetizationAlongProcessInSI process τ *
          volumeInCubicMeters torus.volume =
        torus.amountInMoles *
